import java.util.Scanner;

class Student {
    String name;
    int marks;

    Student() {
        this("Unknown", 0);
    }

    Student(String name, int marks) {
        this.name = name;
        this.marks = marks;
    }

    void displayStudent() {
        System.out.println("Student: " + this.name);
        System.out.println("Marks: " + this.marks);
    }
}

class Scholarship extends Student {
    double attendance;

    Scholarship(String name, int marks, double attendance) {
        super(name, marks);
        this.attendance = attendance;
    }

    void checkEligibility() {
        displayStudent();
        System.out.println("Attendance: " + this.attendance);

        if (this.marks >= 90 && this.attendance >= 75) {
            System.out.println("Scholarship: 10000");
            System.out.println("Status: Eligible");
        } else if (this.marks >= 80 && this.attendance >= 85) {
            System.out.println("Scholarship: 5000");
            System.out.println("Status: Eligible");
        } else {
            System.out.println("Status: Not Eligible");
        }
    }
}

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);

        String name = sc.next();
        int marks = sc.nextInt();
        double attendance = sc.nextDouble();

        Scholarship s = new Scholarship(name, marks, attendance);
        s.checkEligibility();

        sc.close();
    }
}

