import java.util.*;

class Student{
    String name;
    int marks;

    Student(String name,int marks){
        this.name=name;
        this.marks=marks;
    }
}

class Scholarship extends Student{
    double attendance;

    Scholarship(int marks,double attendance){
        super(name,marks);
        this.attendance=attendance;
    }

    void disp(){
        System.out.printf("Student: %s\n",name);
        System.out.printf("Marks: %d\n",marks);
        System.out.printf("Attendance: %.1f\n",attendance);
    }

    void calc(){
        if(marks>=90 && attendance>=75){
            System.out.printf("Scholarship: 10000");
            System.out.printf("Status: Eligible");
        }
        else if(marks>=80 && attendance>=85){
            System.out.printf("Scholarship: 5000");
            System.out.printf("Status: Eligible");
        }
        else{
            System.out.printf("Not Eligible");
        }
    }
}

public class Main{
    public static void main(String[] args){
        Scanner in=new Scanner(System.in);
        String name=in.nextLine();
        int marks=in.nextInt();
        double attendance=in.nextDouble();

        Scholarship s=new Scholarship(int marks,double attendance);
        s.disp();
        s.calc();
    }
}
